CREATE OR REPLACE FUNCTION public.assign_residential_leads(p_lead_ids uuid[], p_operator_ids uuid[], p_only_unassigned boolean DEFAULT true)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  actor public.profiles%rowtype;
  operator public.profiles%rowtype;
  lead public.sales_leads%rowtype;
  operator_count integer;
  assigned_count integer := 0;
  eligible_index integer := 0;
begin
  select * into actor from public.profiles where id = auth.uid();
  if actor.id is null or actor.role <> 'admin' or coalesce(actor.status, '') <> 'active' then
    raise exception 'Only active administrators can assign residential leads.';
  end if;
  if coalesce(cardinality(p_lead_ids),0) not between 1 and 2000
    or cardinality(p_lead_ids) <> (select count(distinct id) from unnest(p_lead_ids) id) then
    raise exception 'Select between 1 and 2000 distinct residential leads.';
  end if;
  operator_count := coalesce(cardinality(p_operator_ids),0);
  if operator_count = 0 or operator_count <> (select count(distinct id) from unnest(p_operator_ids) id) then
    raise exception 'Select at least one distinct active operator.';
  end if;
  -- Lock recipients and leads in a consistent order for concurrent allocations.
  perform id from public.profiles where id = any(p_operator_ids) order by id for share;
  if operator_count <> (select count(*) from public.profiles where id = any(p_operator_ids)
      and role in ('admin','sales','sales_team') and status = 'active') then
    raise exception 'Assignments require active sales-team or administrator accounts.';
  end if;
  perform id from public.sales_leads where id = any(p_lead_ids) order by id for update;
  if cardinality(p_lead_ids) <> (select count(*) from public.sales_leads
      where id = any(p_lead_ids) and business_segment = 'residential') then
    raise exception 'Selection contains unavailable or non-residential leads. Refresh and try again.';
  end if;
  for lead in select * from public.sales_leads where id = any(p_lead_ids) order by id loop
    if coalesce(p_only_unassigned,true) and lead.sales_owner_id is not null then continue; end if;
    select * into operator from public.profiles where id = p_operator_ids[1 + eligible_index % operator_count];
    eligible_index := eligible_index + 1;
    if lead.sales_owner_id is not distinct from operator.id then continue; end if;
    update public.sales_leads set sales_owner_id = operator.id,
      sales_owner_name = coalesce(nullif(operator.full_name,''),operator.email), last_activity_at = now()
      where id = lead.id;
    insert into public.sales_activities(lead_id,user_id,user_name,activity_type,activity_text,metadata)
      values(lead.id,actor.id,coalesce(nullif(actor.full_name,''),actor.email),'assignment',
        'Assigned to ' || coalesce(nullif(operator.full_name,''),operator.email) || '.',
        jsonb_build_object('previous_owner_id',lead.sales_owner_id,'operator_id',operator.id,'business_segment','residential'));
    assigned_count := assigned_count + 1;
  end loop;
  return assigned_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.communication_reserve(p_id text, p_user uuid, p_channel text, p_source text, p_units integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare s communication_settings;r communication_rep_limits;t jsonb;u jsonb;cost integer;secs integer;
begin
 perform pg_advisory_xact_lock(87105020);
 if exists(select 1 from communication_usage where id=p_id) then raise exception 'This communication has already been submitted. Check its status before retrying.';end if;
 select * into s from communication_settings where id;
 if s.paused or (p_channel='call' and s.calls_paused) or (p_channel='sms' and s.texts_paused) then raise exception 'Calling or texting is paused by your administrator.';end if;
 if p_channel not in ('call','sms') or p_units not between 1 and 100 then raise exception 'Invalid communication.';end if;
 if p_channel='call' then secs:=s.max_call_minutes*60;cost:=(s.max_call_minutes+2)*s.voice_cents_per_minute+1;else cost:=p_units*s.sms_cents_per_segment;end if;
 t:=communication_totals();
 if (t->>'daily_cents')::numeric+cost>s.daily_cents or (t->>'monthly_cents')::numeric+cost>s.monthly_cents then raise exception 'Combined calling and texting budget reached. Ask an administrator to review the limits.';end if;
 if p_user is not null then
 select * into r from communication_rep_limits where user_id=p_user;u:=communication_totals(p_user);
 if coalesce(r.paused,false) or (u->>'daily_cents')::numeric+cost>coalesce(r.daily_cents,s.default_rep_daily_cents) or (u->>'monthly_cents')::numeric+cost>coalesce(r.monthly_cents,s.default_rep_monthly_cents) then raise exception 'Your calling and texting allowance has been reached or paused. Ask your administrator.';end if;
 end if;
 insert into communication_usage(id,user_id,channel,source,reserved_cents,units,max_seconds,rate_cents) values(p_id,p_user,p_channel,p_source,cost,p_units,secs,case when p_channel='call' then s.voice_cents_per_minute else s.sms_cents_per_segment end);
 perform communication_alerts();return jsonb_build_object('max_seconds',secs,'reserved_cents',cost);
end$function$

CREATE OR REPLACE FUNCTION public.communication_save_settings(p_user uuid, p_settings jsonb, p_rep uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 perform pg_advisory_xact_lock(87105020);
 if not exists(select 1 from profiles where id=p_user and role='admin' and status='active') then raise exception 'Administrator required';end if;
 if p_rep is null then
 update communication_settings set daily_cents=(p_settings->>'daily_cents')::integer,monthly_cents=(p_settings->>'monthly_cents')::integer,
 paused=(p_settings->>'paused')::boolean,calls_paused=(p_settings->>'calls_paused')::boolean,texts_paused=(p_settings->>'texts_paused')::boolean,
 max_call_minutes=(p_settings->>'max_call_minutes')::integer,default_rep_daily_cents=(p_settings->>'default_rep_daily_cents')::integer,
 default_rep_monthly_cents=(p_settings->>'default_rep_monthly_cents')::integer,voice_cents_per_minute=(p_settings->>'voice_cents_per_minute')::integer,
 sms_cents_per_segment=(p_settings->>'sms_cents_per_segment')::integer,updated_at=now() where id;
 else
 if not exists(select 1 from profiles where id=p_rep and role in ('admin','sales','sales_team')) then raise exception 'Choose a sales member';end if;
 insert into communication_rep_limits(user_id,daily_cents,monthly_cents,paused) values(p_rep,(p_settings->>'daily_cents')::integer,(p_settings->>'monthly_cents')::integer,(p_settings->>'paused')::boolean)
 on conflict(user_id)do update set daily_cents=excluded.daily_cents,monthly_cents=excluded.monthly_cents,paused=excluded.paused;
 end if;
 insert into communication_audit(user_id,details) values(p_user,jsonb_build_object('rep',p_rep,'settings',p_settings));perform communication_alerts();
end$function$

CREATE OR REPLACE FUNCTION public.crm_allocate_region(p_operator_ids uuid[], p_count integer, p_region text DEFAULT ''::text, p_city text DEFAULT ''::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare ids uuid[];
begin
 if not current_user_can_use_sales_portal() or not current_user_has_role(array['admin']) then raise exception 'Administrator access required';end if;
 if p_count not between 1 and 2000 then raise exception 'Choose 1–2000 leads';end if;
 select array_agg(id) into ids from(select id from sales_leads where business_segment='residential' and sales_owner_id is null and pipeline_stage='new_leads' and not do_not_contact and (p_region='' or sales_region=p_region) and (p_city='' or sales_city=p_city) order by id limit p_count for update skip locked)x;
 if coalesce(cardinality(ids),0)=0 then return 0;end if;
 return assign_residential_leads(ids,p_operator_ids,true);
end $function$

CREATE OR REPLACE FUNCTION public.crm_remove_operator_leads_batch(p_operator uuid, p_status text, p_started_at timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare removed_count integer;
begin
  if not current_user_can_use_sales_portal() or not current_user_has_role(array['admin']) then
    raise exception 'Administrator access required';
  end if;
  if p_operator is null or p_started_at is null or p_status is null or p_status not in ('all','new_leads','contacted','interested','link_sent','follow_up','active','lost','followups') then
    raise exception 'Choose a valid lead status';
  end if;
  with batch as (
    select id from sales_leads
    where business_segment='residential' and sales_owner_id=p_operator and updated_at<=p_started_at
      and (p_status='all' or pipeline_stage=p_status or (p_status='followups' and pipeline_stage in ('lost','follow_up')))
    order by id limit 25 for update
  ), released as (
    update sales_leads l set sales_owner_id=null,sales_owner_name=''
    from batch where l.id=batch.id and l.sales_owner_id=p_operator returning l.id
  )
  insert into sales_activities(lead_id,user_id,activity_type,activity_text,metadata)
    select id,auth.uid(),'assignment','Returned to unassigned leads.',jsonb_build_object('previous_owner_id',p_operator,'status_filter',p_status) from released;
  get diagnostics removed_count=row_count;
  return removed_count;
end $function$
